#include <atomic>
#include <cstddef>
#include <type_traits>

class A {};

enum class B : int { e };

static_assert(std::is_arithmetic_v<bool> == true and
    std::is_arithmetic_v<char> == true and std::is_arithmetic_v<char const> == true and
    std::is_arithmetic_v<int> == true and std::is_arithmetic_v<int const> == true and
    std::is_arithmetic_v<float> == true and
    std::is_arithmetic_v<float const> == true and
    std::is_arithmetic_v<std::size_t> == true and

    std::is_arithmetic_v<char &> == false and std::is_arithmetic_v<char *> == false and
    std::is_arithmetic_v<int &> == false and std::is_arithmetic_v<int *> == false and
    std::is_arithmetic_v<float &> == false and
    std::is_arithmetic_v<float *> == false and std::is_arithmetic_v<A> == false and
    std::is_arithmetic_v<B> == false and
    std::is_arithmetic_v<decltype(B::e)> == false and
    std::is_arithmetic_v<std::byte> == false and
    std::is_arithmetic_v<std::atomic_int> == false);

int main() {}
